# Round-robin and least-connections load balancer simulation
import itertools

class RoundRobinBalancer:
    def __init__(self, backends):
        self._pool = itertools.cycle(backends)

    def next_server(self):
        return next(self._pool)

class LeastConnectionsBalancer:
    def __init__(self, backends):
        self._conns = {b: 0 for b in backends}

    def acquire(self):
        server = min(self._conns, key=self._conns.__getitem__)
        self._conns[server] += 1
        return server

    def release(self, server):
        self._conns[server] -= 1

backends = ['web-1:8080', 'web-2:8080', 'web-3:8080']

print('=== Round Robin ===')
rr = RoundRobinBalancer(backends)
for i in range(1, 7):
    print(f'  Request {i} -> {rr.next_server()}')

print('=== Least Connections ===')
lc = LeastConnectionsBalancer(backends)
for req in ['req-a', 'req-b', 'req-c']:
    srv = lc.acquire()
    print(f'  {req} -> {srv}  (conns: {lc._conns})')
lc.release('web-1:8080')
srv = lc.acquire()
print(f'  req-d -> {srv}  (conns: {lc._conns})')
